using Xunit;

namespace Dungeon.Analyzers.Tests;

/// <summary>
/// Generated code is still Core code: source-generated stream handles (M1-05) and anything else
/// marked generated must obey DS11. Roslyn treats a file as generated when it starts with an
/// <c>&lt;auto-generated&gt;</c> comment or is named <c>*.g.cs</c>, <c>*.designer.cs</c> or
/// <c>*.generated.cs</c>; each analyzer must still report there.
/// </summary>
public class GeneratedCodeTests
{
    private const string Header = "// <auto-generated/>\n";

    public static TheoryData<string, string> BannedInGeneratedCode => new()
    {
        { "DUN001", "public sealed class C { private double _d; public double D => _d; }" },
        { "DUN002", "public sealed class C { public int N() => new System.Random(1).Next(); }" },
        { "DUN005", "public sealed class C { public string U(string s) => s.ToUpper(); }" },
        { "DUN006", "public sealed class C { public int S(System.Collections.Generic.HashSet<int> h) { int t = 0; foreach (var x in h) { t += x; } return t; } }" },
        { "DUN007", "public sealed class C { public void S(System.Collections.Generic.List<int> l) => l.Sort(); }" },
        { "DUN010", "public sealed class C { public int Q(int a, int b) => a / b; }" },
        { "DUN011", "public sealed class C { public int W(int a) => unchecked(a + 1); }" },
    };

    [Theory]
    [MemberData(nameof(BannedInGeneratedCode))]
    public void Banned_construct_is_reported_in_a_file_with_an_auto_generated_header(string id, string source)
    {
        var d = Harness.Run(Header + source, "src/Core/Handles.cs");
        Assert.Equal(new[] { id }, Harness.Ids(d));
    }

    [Theory]
    [MemberData(nameof(BannedInGeneratedCode))]
    public void Banned_construct_is_reported_in_a_generated_file_name(string id, string source)
    {
        foreach (var path in new[] { "src/Core/Handles.g.cs", "src/Core/Handles.designer.cs", "src/Core/Handles.generated.cs" })
        {
            var d = Harness.Run(source, path);
            Assert.Equal(new[] { id }, Harness.Ids(d));
        }
    }

    [Fact]
    public void Clean_generated_code_reports_nothing()
    {
        var d = Harness.Run(Header + """
            [assembly: System.Reflection.AssemblyCompanyAttribute("Core")]
            public static partial class StreamHandles
            {
                public static ulong Combat(ulong runSeed) => runSeed ^ 0x9E3779B97F4A7C15UL;
            }
            """, "src/Core/obj/StreamHandles.g.cs");
        Assert.Empty(d);
    }
}
